-- minimal proto builder
local function build_proto(chunk)
  local subs = {}
  local sub_uvs = {}
  for i = 1, #chunk.p do
    subs[i] = build_proto(chunk.p[i])
    sub_uvs[i] = chunk.p[i].upvalues
  end
  local proto = {
    code = chunk.code, k = chunk.k, p = subs, sub_uvs = sub_uvs,
    upvalues = chunk.upvalues,
    num_params = chunk.num_params,
    is_vararg = chunk.is_vararg,
    maxstacksize = chunk.maxstacksize
  }
  return function(upvals) return {proto = proto, upvals = upvals} end
end

